#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

std::vector<std::string> sortByLength(std::vector<std::string> words) {
    std::sort(words.begin(), words.end(), [](const std::string& a, const std::string& b) {
        if (a.size() != b.size()) {
            return a.size() < b.size();
        }
        return a < b;
    });
    return words;
}

int main() {
    std::vector<std::string> words;
    std::string word;
    while (std::cin >> word) {
        words.push_back(word);
    }
    std::vector<std::string> sorted = sortByLength(words);
    for (std::size_t i = 0; i < sorted.size(); i++) {
        if (i > 0) {
            std::cout << " ";
        }
        std::cout << sorted[i];
    }
    std::cout << "\n";
    return 0;
}

